		cols,
		weights,
		Pcol,
		Wtot,
		Ptot,
		Vx,
		Vy,
		H,
		Qx,
		Qy,
		ex,
		ey,
		sol,
		qaAllow,
		ratio: sol.ok ? sol.qmax / qaAllow : Infinity,
		FSsl,
		FSot,
		reqSL,
		reqOT,
