	let vmax = -Infinity;
	let vAt = {
		x: col.x,
		y: col.y
	};
	for (const p of pieces) {
		const v = v0 + a * (p.x - cx) + b * (p.y - cy);
		if (v > vmax) {
			vmax = v;
			vAt = {
				x: p.x,
				y: p.y
			};
		}
	}
	vmax /= 1e3;
	let openSides = 0;
	const cbb = bbCol;
	const probes = [
		{
			x: (cbb.xmin + cbb.xmax) / 2,
			y: cbb.ymin - d / 2
		},
		{
			x: (cbb.xmin + cbb.xmax) / 2,
			y: cbb.ymax + d / 2
		},
		{
			x: cbb.xmin - d / 2,
			y: (cbb.ymin + cbb.ymax) / 2
		},
		{
			x: cbb.xmax + d / 2,
			y: (cbb.ymin + cbb.ymax) / 2
		}
	];
	for (const pr of probes) if (!pointInPolygon(pr, poly)) openSides++;
