		base,
		yCut,
		cutNote,
		AsH,
		horizontalDet: hDet,
		frontVertDet: front,
		rhoV,
		rhoH,
		layers,
		centered: false,
		vertAuto,
		vertRatio,
		horizOn: m.horizOn,
		horizAuto,
		horizLayers: layers,
