		const VuFront = L.V.pool > 0 ? Math.max(0, f.lateral * L.V.pool - f.deadMin * L.V.soil, f.lateral * L.V.pool + f.eq * L.V.poolDyn - f.deadMin * L.V.soil) : 0;
