		const c0 = ext[0].c0;
		const c1 = ext[0].c1;
		const kHi = ext.reduce((b, e, k) => e.c1 > ext[b].c1 ? k : b, 0);
		const kLo = ext.reduce((b, e, k) => e.c0 < ext[b].c0 ? k : b, 0);
