		name: multi ? `Cabezal · punzonamiento de ${q.label}` : "Cabezal · punzonamiento de la columna",
		ratio: q.ratio,
		ok: q.ok,
		detail: `${q.combo}: vu = ${q.vu.toFixed(2)} MPa ≤ φvc = ${q.phivc.toFixed(2)} MPa${q.alphaS < 40 ? ` (αs = ${q.alphaS}, perímetro recortado por el borde)` : ""}`
