		ok: checks.every((c) => c.ok || c.advisory),
		checks,
		warnings,
		pts,
		n,
		capRect: rect,
		capPoly,
		capArea: geom.area,
		capCentroid: {
			x: geom.cx,
			y: geom.cy
		},
		spanX: multi ? [rect.x0, rect.x1] : lineSpan(capPoly, "x", cpp0.cy, cpp0.cx),
